output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper who encounters the entrance cart station is obliged to take the available cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "acquire_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquire_entrance_cart"
    }
  },
  {
    "id": "pick_items_only_with_cart",
    "text": "Items from shelves must only be picked up while the shopper is holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying merchandise by hand instead of using a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "begin_hand_carrying": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_middle_shelf",
    "text": "After collecting the item at the middle shelf location, the shopper is obliged to return the cart to the front return bay.",
    "abstraction": {
      "state_properties": {
        "at_middle_shelf": "at(2,2)",
        "at_front_return_bay": "at(0,1)"
      },
      "events": {
        "middle_shelf_item_collected": {
          "pre": {
            "and": [
              "at_middle_shelf",
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "front_bay_cart_returned": {
          "pre": {
            "and": [
              "at_front_return_bay",
              "LEAVE_CART",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "cartAt(0,1)",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "middle_shelf_item_collected",
      "discharge": "front_bay_cart_returned"
    }
  },
  {
    "id": "leave_cart_only_front_bay",
    "text": "A cart may only be put down at the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)"
      },
      "events": {
        "cart_left_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_front_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_away_from_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {
        "attempt_exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_in_possession"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "attempt_exit_with_cart"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Carts are prohibited in the bottom exit corridor except at the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_corridor_except_cart_station": {
          "or": [
            "at(0,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "bottom_exit_corridor_except_cart_station"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushing_cart_in_exit_corridor"
    }
  },
  {
    "id": "revisit_start_after_cart_return",
    "text": "After returning the cart to the front return bay, the shopper is obliged to revisit the start cell before exiting.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)",
        "at_start_cell": "at(0,5)"
      },
      "events": {
        "front_bay_cart_returned": {
          "pre": {
            "and": [
              "at_front_return_bay",
              "LEAVE_CART",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "cartAt(0,1)",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "front_bay_cart_returned",
      "discharge": "at_start_cell"
    }
  }
]
